import React, { useState, useEffect, useCallback } from 'react';

const ImageViewer = ({ content, closeModal }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const { text = '', images = [], carousel = false } = content || {};
  const validImages = Array.isArray(images) ? images : [];

  const handleNextSlide = useCallback(() => {
    if (carousel && currentImageIndex < validImages.length - 1) {
      setCurrentImageIndex(prevIndex => prevIndex + 1);
    }
  }, [carousel, currentImageIndex, validImages.length]);

  const handlePrevSlide = useCallback(() => {
    if (carousel && currentImageIndex > 0) {
      setCurrentImageIndex(prevIndex => prevIndex - 1);
    }
  }, [carousel, currentImageIndex]);


  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'Escape') {
        closeModal();
      } else if (e.key === 'ArrowLeft' && carousel && currentImageIndex > 0) {
        handlePrevSlide();
      } else if (e.key === 'ArrowRight' && carousel && currentImageIndex < validImages.length - 1) {
        handleNextSlide();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    document.body.style.overflow = 'hidden';


    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'auto';
    };
  }, [closeModal, carousel, currentImageIndex, handleNextSlide, handlePrevSlide, validImages.length]);

  if (!content) return null;

  return (
    <div className="modal-overlay" onClick={closeModal} style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      backgroundColor: 'rgba(0, 0, 0, 0.85)',
      display: 'flex',
      alignItems: 'flex-end',  // Align items to the bottom
      justifyContent: 'flex-end', // Align items to the right
      zIndex: 10000,
      pointerEvents: 'auto'
    }}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{
        backgroundColor: 'white',
        borderRadius: '8px',
        padding: '24px',
        maxWidth: '40%',  // Reduced max-width
        maxHeight: '40%', // Reduced max-height
        overflow: 'auto',
        position: 'relative',
        marginRight: '24px', // Added right margin
        marginBottom: '24px', // Added bottom margin
      }}>
        {validImages.length > 0 && (
          <div className="image-container" style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}>
            {carousel && validImages.length > 1 ? (
              <>
                <img
                  className="modal-image"
                  src={validImages[currentImageIndex]}
                  alt={`Slide ${currentImageIndex + 1}`}
                  style={{
                    maxWidth: '100%',
                    maxHeight: '100%', // Ensure image fits within the smaller container
                  }}
                />
                <div className="carousel-controls" style={{
                  position: 'absolute',
                  top: '50%',
                  left: 0,
                  right: 0,
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}>
                  {currentImageIndex > 0 && (
                    <button
                      className="prev-btn"
                      onClick={handlePrevSlide}
                      style={{
                        backgroundColor: 'rgba(0, 0, 0, 0.5)',
                        color: 'white',
                        border: 'none',
                        padding: '10px',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        fontSize: '24px',
                      }}
                    >
                      &#10094;
                    </button>
                  )}
                  {currentImageIndex < validImages.length - 1 && (
                    <button
                      className="next-btn"
                      onClick={handleNextSlide}
                      style={{
                        backgroundColor: 'rgba(0, 0, 0, 0.5)',
                        color: 'white',
                        border: 'none',
                        padding: '10px',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        fontSize: '24px',
                      }}
                    >
                      &#10095;
                    </button>
                  )}
                </div>
              </>
            ) : (
              <img
                className="modal-image"
                src={validImages[0]}
                alt="Modal"
                style={{
                  maxWidth: '100%',
                  maxHeight: '100%', // Ensure image fits within the smaller container.
                }}
              />
            )}
          </div>
        )}

        {text && (
          <div
            className="modal-caption"
            dangerouslySetInnerHTML={{ __html: text }}
            style={{
              marginTop: '16px',
              color: '#333',
              fontSize: '0.8rem', //make font smaller
              maxWidth: '80%',  // Caption width
              textAlign: 'left' //align text left
            }}
          />
        )}

        <button
          className="close-btn"
          onClick={closeModal}
          style={{
            position: 'absolute',
            top: '8px',
            right: '8px',
            backgroundColor: 'transparent',
            border: 'none',
            fontSize: '24px',
            cursor: 'pointer',
            color: '#555',
          }}
        >
          &times;
        </button>
      </div>
    </div>
  );
};

export default ImageViewer;
